const $=s=>document.querySelector(s);
const isChordSymbol=value=>window.TayWineChords.isChordSymbol(value);
const safeRead=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const persist=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{}};
const state={songs:[],view:'discover',filter:'all',query:'',limit:12,artist:'',current:null,transpose:0,font:16,lyricsOnly:false,scrolling:false};
const favorites=new Set(safeRead('mcm-favorites',[]));
let scrollTimer,toastTimer,loadToken=0;
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>s.normalize('NFC').toLocaleLowerCase().replace(/[\u200b-\u200d\ufeff]/g,'').trim();
const cover=(i)=>`<span class="cover c${i%5}"><span>${['♫','✳','♬','✧','♪'][i%5]}</span></span>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
function updateFavorites(){ $('#fav-count').textContent=favorites.size;persist('mcm-favorites',[...favorites]);document.querySelectorAll('[data-favorite]').forEach(b=>{const yes=favorites.has(b.dataset.favorite);b.classList.toggle('saved',yes);b.textContent=yes?'♥':'♡';b.setAttribute('aria-label',yes?'Remove from songbook':'Save to songbook');b.setAttribute('aria-pressed',String(yes))});if($('#reader-save'))$('#reader-save').textContent=favorites.has(state.current?.id)?'♥ Songbook ထဲ သိမ်းထားသည်':'♡ Songbook ထဲ သိမ်းမယ်'}
function toggleFavorite(id){const added=!favorites.has(id);added?favorites.add(id):favorites.delete(id);updateFavorites();toast(added?'Songbook ထဲ သိမ်းပြီးပါပြီ':'Songbook မှ ဖယ်ပြီးပါပြီ');if(state.view==='favorites'&&!state.current)renderList()}
function filtered(){let list=state.songs.filter(s=>(state.view!=='favorites'||favorites.has(s.id))&&(!state.artist||s.artist===state.artist)&&(state.filter==='all'||(state.filter==='chords'?s.hasChords:!s.hasChords)));if(state.query){const q=normalize(state.query);list=list.filter(s=>normalize(s.title+' '+s.artist+' '+s.key).includes(q))}if(state.easyOnly)list=list.filter(s=>s.beginner_friendly);if(state.discoveryMode==='trending')list=list.filter(s=>Date.parse(s.source_added_at)>=Date.now()-90*86400000);if(state.discoveryMode==='recent')list=list.filter(s=>(state.recentIds||[]).includes(s.id)).sort((a,b)=>state.recentIds.indexOf(a.id)-state.recentIds.indexOf(b.id));const sort=$('#sort').value;if(sort==='source_views')list=[...list].sort((a,b)=>(b.source_views??-1)-(a.source_views??-1));else if(sort==='source_added_at')list=[...list].sort((a,b)=>(Date.parse(b.source_added_at)||0)-(Date.parse(a.source_added_at)||0));else if(sort!=='default')list=[...list].sort((a,b)=>a[sort].localeCompare(b[sort],'my'));if(state.view==='discover'&&!state.query&&sort==='default'){const seen=new Set(),first=[],rest=[];for(const song of list){if(seen.has(song.artist))rest.push(song);else{seen.add(song.artist);first.push(song)}}list=[...first,...rest]}return list}
function renderList(){const list=filtered();$('#result-count').textContent=`${list.length.toLocaleString()} ပုဒ်အနက် ${Math.min(state.limit,list.length).toLocaleString()} ပုဒ် ပြထားသည်`;$('#song-list').innerHTML=list.slice(0,state.limit).map((s,i)=>`<div class="song-row"><span class="row-number">${String(i+1).padStart(2,'0')}</span><button class="song-main" data-song="${s.id}">${window.Nyoh?.cover(s)||cover(Number(s.id))}<span class="song-info"><span class="song-title">${escapeHtml(s.title)}</span><span class="song-subtitle">${escapeHtml(s.artist)} · ${s.hasChords?'CHORDS + LYRICS':'LYRICS'}</span></span></button><button class="artist-cell" data-artist="${escapeHtml(s.artist)}">${escapeHtml(s.artist)}</button><span class="key-pill">${escapeHtml(s.key||'—')}</span><button class="favorite-button ${favorites.has(s.id)?'saved':''}" data-favorite="${s.id}" aria-label="Save to songbook" aria-pressed="${favorites.has(s.id)}">${favorites.has(s.id)?'♥':'♡'}</button></div>`).join('')||`<div class="empty-state"><strong>${state.view==='favorites'?'ကိုယ်ပိုင် songbook လေး စလိုက်ရအောင်။':'သီချင်း မတွေ့သေးပါ။'}</strong>${state.view==='favorites'?'သီချင်းဘေးက ♡ ကို နှိပ်ပြီး သိမ်းထားနိုင်ပါတယ်။':'အခြားသီချင်းနာမည် သို့မဟုတ် အဆိုတော်နာမည်နဲ့ ရှာကြည့်ပါ။'}</div>`;$('#load-more').hidden=list.length<=state.limit}
function renderArtists(){const groups=new Map();for(const s of state.songs){if(state.query&&!normalize(s.artist).includes(normalize(state.query)))continue;groups.set(s.artist,(groups.get(s.artist)||0)+1)}$('#artist-grid').innerHTML=[...groups].sort((a,b)=>b[1]-a[1]).map(([artist,count])=>`<button class="artist-card" data-artist="${escapeHtml(artist)}"><span class="artist-avatar">♫</span><span><b>${escapeHtml(artist)}</b><small>${count} songs ↗</small></span></button>`).join('')||'<div class="empty-state">အဆိုတော် မတွေ့ပါ။</div>';$('#load-more').hidden=true}
function setView(view,{keepQuery=false}={}){stopScroll();window.TayWinePractice?.exitFocus();loadToken++;state.current=null;state.view=view;state.artist='';state.easyOnly=false;state.discoveryMode='';state.limit=view==='discover'?12:30;if(!keepQuery){state.query='';$('#search').value='';$('#clear-search').hidden=true}$('#home-view').hidden=false;$('#reader-view').hidden=true;$('#hero').hidden=view!=='discover'||!!state.query;$('#collections').hidden=view!=='discover'||!!state.query;$('#library').hidden=view==='artists';$('#artist-panel').hidden=view!=='artists';$('#list-title').textContent=view==='favorites'?'ကိုယ့်အကြိုက် သီချင်းများ':view==='songs'?'သီချင်းအားလုံး':'တီးချင်စရာ သီချင်းတွေ';$('#list-eyebrow').textContent=view==='favorites'?'YOUR PERSONAL SONGBOOK':'YOUR NEXT PLAY';$('#view-all').hidden=view!=='discover';document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===view));view==='artists'?renderArtists():renderList();window.scrollTo({top:0,behavior:'instant'});window.Nyoh?.renderDiscover()}
function artistView(artist){setView('songs');state.artist=artist;$('#list-title').textContent=artist;$('#list-eyebrow').textContent='ARTIST SONGBOOK';renderList();$('#library').scrollIntoView({behavior:'smooth',block:'start'})}
const notes=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];
const flats={Db:'C#',Eb:'D#',Gb:'F#',Ab:'G#',Bb:'A#',Cb:'B',Fb:'E'};
function transposeChord(chord,steps){if(!steps||!isChordSymbol(chord))return chord;return chord.replace(/(^|\/)([A-G](?:#|b)?)/g,(_,slash,n)=>{const i=notes.indexOf(flats[n]||n);return slash+(i<0?n:notes[(i+steps%12+12)%12])})}
function renderSheet(){if(!state.current)return;const s=state.current;const body=state.lyricsOnly?s.lyrics:s.chordpro;$('#sheet').style.fontSize=state.font+'px';$('#sheet').innerHTML=body.split('\n').map(line=>{const heading=line.match(/^\s*\{(.*?)\}\s*$/);if(heading)return `<div class="sheet-section">${escapeHtml(heading[1])}</div>`;if(state.lyricsOnly||!line.includes('['))return `<div class="sheet-line plain">${escapeHtml(line)||'&nbsp;'}</div>`;const units=[];let last=0;let currentChord='';for(const m of line.matchAll(/\[([^\]]+)\]/g)){if(!isChordSymbol(m[1]))continue;if(m.index>last)units.push([currentChord,line.slice(last,m.index)]);else if(currentChord)units.push([currentChord,'']);currentChord=m[1];last=m.index+m[0].length}units.push([currentChord,line.slice(last)]);return `<div class="sheet-line">${units.map(([chord,text])=>`<span class="lyric-unit"><span class="chord">${escapeHtml(transposeChord(chord,state.transpose))||'&nbsp;'}</span><span class="lyric-text">${escapeHtml(text)||'&nbsp;'}</span></span>`).join('')}</div>`}).join('');$('#current-key').textContent=transposeChord(s.key||'—',state.transpose);$('#transpose-note').textContent=state.transpose===0?'Original key':`${state.transpose>0?'+':''}${state.transpose} semitones`;$('#lyrics-toggle').classList.toggle('on',state.lyricsOnly);$('#lyrics-toggle').textContent=state.lyricsOnly?'Chords + Lyrics':'Lyrics only';window.TayWinePractice?.renderChords()}
async function openSong(id,{hash=true}={}){stopScroll();const token=++loadToken;$('#home-view').hidden=true;$('#reader-view').hidden=false;$('#reader-content').innerHTML='<div class="loading">သီချင်းဖွင့်နေပါသည်…</div>';window.scrollTo({top:0,behavior:'instant'});try{const res=await fetch(`songs/${encodeURIComponent(id)}.json`);if(!res.ok)throw Error('Song unavailable');const s=await res.json();if(token!==loadToken)return;state.current=s;state.transpose=0;state.lyricsOnly=false;if(hash)history.pushState(null,'',`#song/${id}`);$('#reader-content').innerHTML=`<div class="reader-top"><div><span class="reader-tag">TAYWINE SONGBOOK / ${s.has_chords===false?'LYRICS':'CHORDS & LYRICS'}</span><h1>${escapeHtml(s.title)}</h1><div class="reader-artist">${escapeHtml(s.artist)}${s.album?' · '+escapeHtml(s.album):''}</div></div><button class="reader-favorite" id="reader-save">♡ Songbook ထဲ သိမ်းမယ်</button></div><div class="reader-tools"><div class="tool-group"><label>KEY</label><button id="key-down" aria-label="Transpose down">−</button><strong id="current-key"></strong><button id="key-up" aria-label="Transpose up">+</button><span id="transpose-note"></span></div><div class="tool-group"><label>TEXT</label><button id="font-down" aria-label="Smaller text">A−</button><button id="font-up" aria-label="Larger text">A+</button></div><button id="lyrics-toggle">Lyrics only</button><section class="scroll-control" aria-label="Auto-scroll controls"><div class="scroll-control-title"><span class="scroll-control-label">AUTO-SCROLL</span><span id="scroll-status" role="status">Paused</span></div><div class="scroll-control-main"><button id="scroll-toggle" aria-label="Start auto-scroll" aria-pressed="false">▷ <span>Start</span></button><div class="scroll-speed-input"><button id="speed-down" aria-label="Decrease scroll speed">−</button><label class="speed-number-wrap"><span class="sr-only">Scroll speed multiplier</span><input id="scroll-speed" type="number" min="0.1" max="10" step="0.1" value="1" inputmode="decimal" aria-describedby="scroll-help"><span>×</span></label><button id="speed-up" aria-label="Increase scroll speed">+</button></div><label class="scroll-slider-wrap"><span class="sr-only">Adjust scroll speed</span><input id="scroll-range" type="range" min="0.1" max="10" step="0.1" value="1"><span class="scroll-range-labels"><span>0.1× · နှေး</span><span>10× · မြန်</span></span></label><button id="speed-reset" class="scroll-reset" aria-label="Reset speed to 1x">Reset 1×</button></div><p id="scroll-help">အမြန်နှုန်းကို နံပါတ်ရိုက်ထည့်ပါ၊ slider ဆွဲပါ၊ သို့မဟုတ် − / + နှိပ်ပါ။</p></section><button id="print-song">Print ↗</button><button id="share-song">Copy link ↗</button></div><article id="sheet" class="song-sheet" aria-label="Song lyrics and chords"></article><div class="reader-source">မူရင်း key: ${escapeHtml(s.key||'မဖော်ပြထား')} · Source: <a href="${escapeHtml(s.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(s.source)} ↗</a><br>စာသားနဲ့ chord တွေကို မူရင်းစာမျက်နှာအတိုင်း ဖော်ပြထားပါသည်။</div>`;renderSheet();updateFavorites();window.Nyoh?.songReady(s);$('#reader-save').onclick=()=>toggleFavorite(id);$('#key-down').onclick=()=>{state.transpose=Math.max(-11,state.transpose-1);renderSheet()};$('#key-up').onclick=()=>{state.transpose=Math.min(11,state.transpose+1);renderSheet()};$('#font-down').onclick=()=>{state.font=Math.max(12,state.font-1);renderSheet()};$('#font-up').onclick=()=>{state.font=Math.min(28,state.font+1);renderSheet()};$('#lyrics-toggle').onclick=()=>{state.lyricsOnly=!state.lyricsOnly;renderSheet()};setupScrollControls();$('#print-song').onclick=()=>window.print();$('#share-song').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);toast('သီချင်း link ကူးပြီးပါပြီ')}catch{toast('Browser address bar မှ link ကို ကူးယူနိုင်ပါတယ်။')}}}catch(e){if(token!==loadToken)return;$('#reader-content').innerHTML='<div class="empty-state"><strong>သီချင်းဖွင့်လို့ မရသေးပါ။</strong>စာရင်းသို့ပြန်သွားပြီး ထပ်ဖွင့်ကြည့်ပါ။</div>'}}
let scrollSpeed=1;
function setScrollSpeed(value){const parsed=Number(value);if(!Number.isFinite(parsed))return;scrollSpeed=Math.round(Math.min(10,Math.max(.1,parsed))*10)/10;const number=$('#scroll-speed'),range=$('#scroll-range');if(number)number.value=String(scrollSpeed);if(range){range.value=String(scrollSpeed);range.setAttribute('aria-valuetext',scrollSpeed+' times speed')}persist('nyoh-scroll-speed',scrollSpeed);if(state.scrolling&&$('#scroll-status'))$('#scroll-status').textContent='Playing · '+scrollSpeed+'×'}
function setupScrollControls(){const stored=Number(safeRead('nyoh-scroll-speed',1));setScrollSpeed(Number.isFinite(stored)&&stored>0?stored:1);$('#scroll-toggle').onclick=toggleScroll;$('#speed-down').onclick=()=>setScrollSpeed(scrollSpeed-.1);$('#speed-up').onclick=()=>setScrollSpeed(scrollSpeed+.1);$('#speed-reset').onclick=()=>setScrollSpeed(1);$('#scroll-range').oninput=e=>setScrollSpeed(e.target.value);$('#scroll-speed').oninput=e=>{const n=Number(e.target.value);if(e.target.value!==''&&n>=.1&&n<=10)setScrollSpeed(n)};$('#scroll-speed').onchange=e=>setScrollSpeed(e.target.value===''?scrollSpeed:e.target.value);$('#scroll-speed').onkeydown=e=>{if(e.key==='Enter')e.target.blur()}}
function updateScrollButton(running){const b=$('#scroll-toggle');if(b){b.innerHTML=(running?'Ⅱ':'▷')+' <span>'+(running?'Pause':'Start')+'</span>';b.classList.toggle('on',running);b.setAttribute('aria-label',running?'Pause auto-scroll':'Start auto-scroll');b.setAttribute('aria-pressed',String(running))}if($('#scroll-status'))$('#scroll-status').textContent=running?'Playing · '+scrollSpeed+'×':'Paused'}
function stopScroll(){cancelAnimationFrame(scrollTimer);state.scrolling=false;updateScrollButton(false)}
function toggleScroll(){if(state.scrolling){stopScroll();return}state.scrolling=true;updateScrollButton(true);let last=performance.now(),carry=0;const step=t=>{if(!state.scrolling)return;carry+=Math.min(t-last,100)*scrollSpeed*.035;last=t;if(carry>=1){const n=Math.floor(carry);window.scrollBy(0,n);carry-=n}if(window.innerHeight+window.scrollY>=document.documentElement.scrollHeight-2){stopScroll();return}scrollTimer=requestAnimationFrame(step)};scrollTimer=requestAnimationFrame(step)}
window.addEventListener('wheel',()=>{if(state.scrolling)stopScroll()},{passive:true});window.addEventListener('touchmove',e=>{if(state.scrolling&&!e.target.closest?.('.scroll-control'))stopScroll()},{passive:true});
function randomSong(){if(window.Nyoh)return window.Nyoh.drawSong();const list=state.songs.filter(s=>s.hasChords);if(list.length)openSong(list[Math.floor(Math.random()*list.length)].id)}
document.addEventListener('click',e=>{const view=e.target.closest('[data-view]');if(view){history.replaceState(null,'',location.pathname);setView(view.dataset.view);return}const fav=e.target.closest('[data-favorite]');if(fav){toggleFavorite(fav.dataset.favorite);return}const song=e.target.closest('[data-song]');if(song){openSong(song.dataset.song);return}const artist=e.target.closest('[data-artist]');if(artist)artistView(artist.dataset.artist)});
$('#search').addEventListener('input',()=>{state.query=$('#search').value;state.limit=30;$('#clear-search').hidden=!state.query;$('#hero').hidden=state.view!=='discover'||!!state.query;$('#collections').hidden=state.view!=='discover'||!!state.query;state.view==='artists'?renderArtists():renderList();window.Nyoh?.renderDiscover()});$('#clear-search').onclick=()=>{$('#search').value='';$('#search').dispatchEvent(new Event('input'));$('#search').focus()};
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;state.limit=30;document.querySelectorAll('[data-filter]').forEach(n=>n.classList.toggle('selected',n===b));renderList()});$('#sort').onchange=renderList;$('#load-more').onclick=()=>{state.limit+=30;renderList()};$('#view-all').onclick=()=>{setView('songs');$('#library').scrollIntoView({behavior:'smooth'})};$('#random-side').onclick=randomSong;$('#hero-play').onclick=randomSong;
document.querySelectorAll('[data-mood]').forEach(b=>b.onclick=()=>{setView('songs');const mood=b.dataset.mood;if(mood==='love'){state.query='ချစ်';$('#search').value=state.query;$('#clear-search').hidden=false;$('#list-title').textContent='အချစ်သီချင်းများ'}else if(mood==='acoustic'){state.filter='chords';$('#sort').value='title';$('#list-title').textContent='ဂစ်တာနဲ့ တီးကြည့်မယ်'}else{randomSong();return}document.querySelectorAll('[data-filter]').forEach(n=>n.classList.toggle('selected',n.dataset.filter===state.filter));renderList();$('#library').scrollIntoView({behavior:'smooth'})});
$('#reader-back').onclick=()=>{history.replaceState(null,'',location.pathname);setView(state.view,{keepQuery:true})};$('#theme-toggle').onclick=()=>{document.body.classList.toggle('dark');persist('mcm-dark',document.body.classList.contains('dark'))};if(safeRead('mcm-dark',false))document.body.classList.add('dark');
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){e.preventDefault();if(state.current)setView('songs');$('#search').focus()}if(e.key==='Escape'){if(state.current)$('#reader-back').click();else $('#search').blur()}});window.addEventListener('popstate',()=>{const id=location.hash.match(/^#song\/(\d+)$/)?.[1];id?openSong(id,{hash:false}):setView(state.view,{keepQuery:true})});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopScroll()});
(async()=>{try{const res=await fetch('catalog.json');if(!res.ok)throw Error('Catalog unavailable');state.songs=await res.json();$('#catalog-count').textContent=`${state.songs.length.toLocaleString()} သီချင်း · ${new Set(state.songs.map(s=>s.artist)).size.toLocaleString()} အဆိုတော်`;renderList();updateFavorites();window.Nyoh?.renderDiscover();const id=location.hash.match(/^#song\/(\d+)$/)?.[1];if(id)openSong(id,{hash:false})}catch{$('#catalog-count').textContent='သီချင်းစာရင်း ဖွင့်မရပါ';$('#song-list').innerHTML='<div class="empty-state"><strong>စာရင်းဖွင့်မရသေးပါ။</strong>အင်တာနက် စစ်ပြီး စာမျက်နှာကို ပြန်ဖွင့်ကြည့်ပါ။</div>'}})();

